/// <summary>
/// Dựng bảng chi tiết điểm toàn khóa.
/// - Quy chế tín chỉ (44, 99, 43): mỗi môn 3 cột TKM, QĐSố, QĐChữ.
/// - Quy chế còn lại (14, ...): mỗi môn 1 cột TKM.
/// Cấu trúc giống mẫu Leaning_BangDiem_ToanKhoa19_QC14.repx / Leaning_BangDiem_ToanKhoa_28QC99.repx.
/// </summary>
private string DetailToHTML(bool bolTinChi)
{
    string strHeader1 = "<tr>";
    string strHeader2 = "<tr>";
    string strHeader3 = ""; // hàng tín chỉ / ĐVHT
    string strRows = "";

    int intRowspan = bolTinChi ? 3 : 2;

    // Cột cố định phía trước
    strHeader1 += "<th rowspan='" + intRowspan.ToString() + "' style='width:25px'>TT</th>"
                + "<th rowspan='" + intRowspan.ToString() + "' style='width:65px'>Mã số</th>"
                + "<th rowspan='" + intRowspan.ToString() + "' style='width:130px'>Họ và tên</th>";

    foreach (DataRow drwSubject in dtbClassSubject.Rows)
    {
        string strSubjectName = drwSubject["SubjectShortName"].ToString();
        string strUnitText = drwSubject["UnitText"].ToString();
        if (strUnitText == "")
            strUnitText = "&nbsp;";

        if (bolTinChi)
        {
            // Hàng 1: tên môn xoay dọc, colspan=3 (TKM / QĐSố / QĐChữ)
            strHeader1 += "<th colspan='3' class='subject'><span>" + strSubjectName + "</span></th>";
            // Hàng 2: nhãn 3 cột con
            strHeader2 += "<th class='subcol'>TKM</th><th class='subcol'>QĐSố</th><th class='subcol'>QĐChữ</th>";
            // Hàng 3: số tín chỉ
            if (strHeader3 == "")
                strHeader3 = "<tr>";
            strHeader3 += "<td colspan='3'>" + strUnitText + "</td>";
        }
        else
        {
            // Hàng 1: tên môn xoay dọc (Angle=90° như mẫu QC14)
            strHeader1 += "<th class='subject'><span>" + strSubjectName + "</span></th>";
            // Hàng 2: số đơn vị học trình
            strHeader2 += "<td>" + strUnitText + "</td>";
        }
    }

    // Cột cố định phía sau
    strHeader1 += "<th rowspan='" + intRowspan.ToString() + "' style='width:55px'>TBC</th>"
                + "<th rowspan='" + intRowspan.ToString() + "' style='width:72px'>Xếp loại học tập</th>"
                + "<th rowspan='" + intRowspan.ToString() + "' style='width:72px'>Xếp loại rèn luyện</th>";
    strHeader1 += "</tr>";
    strHeader2 += "</tr>";
    if (bolTinChi)
        strHeader3 += "</tr>";

    // Dữ liệu sinh viên
    int intTT = 1;
    foreach (DataRow drwStudent in dtbData.Rows)
    {
        string strRow = "<tr>"
            + "<td>" + intTT.ToString() + "</td>"
            + "<td>" + drwStudent["StudentCode"].ToString() + "</td>"
            + "<td class='name'>" + drwStudent["StudentFirstName"].ToString() + " " + drwStudent["StudentLastName"].ToString() + "</td>";

        int j = 1;
        foreach (DataRow drwSubject in dtbClassSubject.Rows)
        {
            string strFinal = FormatMark(drwStudent["FinalSummary_" + j.ToString()].ToString());

            if (bolTinChi)
            {
                string strOther = FormatMark(drwStudent["OtherFinalSummary_" + j.ToString()].ToString());
                string strLevel = drwStudent["LearningLevel_" + j.ToString()].ToString();
                string strStyle = MarkRedStyle(strFinal);
                strRow += "<td" + strStyle + ">" + strFinal + "</td>"
                        + "<td>" + strOther + "</td>"
                        + "<td>" + strLevel + "</td>";
            }
            else
            {
                strRow += "<td" + MarkRedStyle(strFinal) + ">" + strFinal + "</td>";
            }
            j++;
        }

        strRow += "<td class='bold'>" + drwStudent["SummaryLearningMark"].ToString() + "</td>"
                + "<td>" + drwStudent["LearningLevel"].ToString() + "</td>"
                + "<td>" + drwStudent["EthicLevel"].ToString() + "</td>"
                + "</tr>";
        strRows += strRow;
        intTT++;
    }

    return "<table class='main'>"
        + strHeader1
        + strHeader2
        + (bolTinChi ? strHeader3 : "")
        + strRows
        + "</table>";
}

/// <summary>
/// Điểm &lt; 5 tô đỏ (bỏ qua M/Đ/CĐ và chuỗi rỗng).
/// </summary>
private string MarkRedStyle(string strFinal)
{
    if (strFinal == "" || strFinal == "M" || strFinal == "Đ" || strFinal == "CĐ")
        return "";
    try
    {
        if (Convert.ToDouble(strFinal.Replace(",", ".")) < 5)
            return " class='markRed'";
    }
    catch
    {
    }
    return "";
}

